      "category": "concept"
    },
    {
      "name": "联合分布函数",
      "aliases": ["joint distribution function", "二维联合分布函数"],
      "definition_snippet": "F(x, y) = P(X ≤ x, Y ≤ y)。",
      "category": "concept"
    },
    {
      "name": "联合概率密度",
      "aliases": ["joint probability density", "联合密度"],
      "definition_snippet": "描述二维连续型随机变量联合分布密度的函数 f(x, y)。",
      "category": "concept"
    },
    {
      "name": "边缘分布",
      "aliases": ["marginal distribution", "边缘分布总体"],
      "definition_snippet": "由联合分布得到的单个随机变量的分布。",
      "category": "concept"
    },
    {
      "name": "边缘分布函数",
      "aliases": ["marginal distribution function", "边缘函数"],
      "definition_snippet": "F_X(x) = F(x, +∞)，F_Y(y) = F(+∞, y)。",
      "category": "concept"
    },
    {
      "name": "边缘概率密度",
      "aliases": ["marginal probability density", "边缘密度"],
      "definition_snippet": "f_X(x) = ∫ f(x, y)dy，f_Y(y) = ∫ f(x, y)dx。",
      "category": "concept"
    },
    {
      "name": "条件分布",
      "aliases": ["conditional distribution", "条件分布总体"],
      "definition_snippet": "在某一随机变量取值条件下另一随机变量的分布。",
      "category": "concept"
    },
    {
      "name": "条件概率密度",
      "aliases": ["conditional probability density", "条件密度"],
      "definition_snippet": "f_{X|Y}(x|y) = f(x, y) / f_Y(y)。",
      "category": "concept"
    },
    {
      "name": "条件分布函数",
      "aliases": ["conditional distribution function", "条件分布函数形式"],
      "definition_snippet": "F_{X|Y}(x|y) = P(X ≤ x | Y = y)。",
      "category": "concept"
    },
    {
      "name": "随机变量的独立性",
      "aliases": ["independence of random variables", "独立性"],
      "definition_snippet": "X 与 Y 独立当且仅当联合分布等于边缘分布的乘积。",
      "category": "property"
    },
    {
